.window-panel { position: absolute; inset: 12px 12px 12px var(--window-panel-inset, 340px); z-index: 15; display: flex; flex-direction: column; min-width: 0; max-width: calc(100% - 24px); max-height: calc(100% - 24px); background: var(--panel-background); color: var(--fg); border: 1px solid var(--gutter); border-radius: var(--panel-radius); overflow: clip; box-shadow: var(--shadow-panel); }
.window-panel-header { display: flex; align-items: center; flex-wrap: wrap; gap: var(--space-5); padding: var(--space-5) var(--space-7); border-bottom: 1px solid var(--gutter); }
.window-panel-header > div { flex: 1; min-width: 100px; }
.window-panel-header strong { display: block; font-size: var(--text-lg); }
.window-panel-header small { display: block; color: var(--muted); font-size: var(--text-sm); margin-top: 4px; }
.window-panel button, .window-panel select { color: var(--fg); border: 1px solid var(--gutter); border-radius: var(--control-radius); background: var(--control-background); padding: 5px var(--space-4); font: inherit; font-size: var(--text-md); cursor: pointer; }
.window-panel button:disabled { opacity: .45; cursor: default; }
.window-panel :focus-visible { outline: 2px solid var(--accent-primary); outline-offset: -2px; }
.window-panel-header label { color: var(--muted); font-size: var(--text-sm); }
.window-panel-workspace, .window-panel-content { display: flex; min-height: 0; min-width: 0; flex: 1; }
.window-panel-content { flex-direction: column; }
.window-panel-panes { display: flex; flex: 1; min-height: 0; min-width: 0; }
.window-panel-primary, .window-panel-secondary { min-width: 0; min-height: 0; flex: 1; display: flex; flex-direction: column; }
.window-panel-full-split .window-panel-primary { flex: 0 0 var(--tree-ratio); }
.window-panel-divider { flex: 0 0 6px; cursor: col-resize; touch-action: none; background: var(--surface-control); }
.window-panel-divider:hover, .window-panel-divider:focus-visible { background: var(--border-strong); }
.window-panel-tabs { display: flex; gap: var(--space-2); padding: var(--space-4); border-bottom: 1px solid var(--gutter); }
.window-panel-tabs [aria-selected=true] { background: var(--surface-selected); border-color: var(--accent-primary); }
.window-panel-canvas { position: relative; flex: 0 0 44%; min-width: 0; overflow: hidden; border-right: 1px solid var(--gutter); }
.window-panel-canvas .change-session-actions { left: 10px; right: 10px; flex-wrap: wrap; gap: var(--space-3); }
.window-panel-canvas .change-preview-message { left: 12px; }
.window-panel-message { padding: 18px; color: var(--muted); font-size: var(--text-lg); }
.window-panel-message[role=alert] { color: var(--accent-danger); }
.diff-pane-toolbar { display: flex; gap: var(--space-3); align-items: center; flex-wrap: wrap; padding: var(--space-4) var(--space-5); min-height: 40px; border-bottom: 1px solid var(--border-subtle); }
.diff-pane-toolbar > span { flex: 1; font-size: var(--text-sm); color: var(--muted); }
.diff-tree-scroll { overflow: auto; flex: 1; padding: 20px var(--space-7); }
.diff-tree-ascii { font: var(--text-md)/2 var(--font-mono); margin: 0; min-width: max-content; }
.diff-tree-ascii [role=treeitem] { cursor: pointer; border-radius: var(--radius-sm); padding-block: 3px; }
.diff-tree-ascii [aria-selected=true] { color: var(--selection-text); background: var(--selection-fill); outline: 1px solid var(--selection-border); }
.diff-tree-ascii [data-mapped=true] { text-decoration: underline dotted var(--border-strong); text-underline-offset: 5px; }
.diff-tree-ascii [role=treeitem]:hover { background: var(--surface-hover); }
.diff-hunks-scroll { flex: 1; overflow: auto; min-height: 0; padding: 0 0 20px; }
.diff-hunk { content-visibility: auto; contain-intrinsic-size: auto 260px; border-bottom: 1px solid var(--border-subtle); }
.diff-hunk-header { display: flex; gap: var(--space-4); align-items: center; flex-wrap: wrap; position: sticky; top: 0; z-index: 1; padding: 9px var(--space-6); background: var(--surface-raised); font-size: var(--text-md); }
.diff-hunk-header strong { flex: 1; overflow-wrap: anywhere; }
.diff-hunk-header small { color: var(--text-muted); font: var(--text-xs) var(--font-mono); }
.diff-hunk-header .diff-count-added { color: var(--change-added); } .diff-hunk-header .diff-count-removed { color: var(--change-deleted); }
.diff-hunk-range { padding: var(--space-3) var(--space-6); color: var(--text-muted); background: var(--selection-fill); font: var(--text-sm) var(--font-mono); }
.diff-hunk-code { font: var(--text-md)/20px var(--font-mono); tab-size: 4; margin: 0; min-width: max-content; }
.diff-hunk-row { display: flex; min-height: 20px; border-left: 2px solid transparent; }
.diff-hunk-row[data-kind=add] { background: var(--diff-hunk-added-fill); border-left-color: var(--diff-added-border); }
.diff-hunk-row[data-kind=delete] { background: var(--diff-hunk-deleted-fill); border-left-color: var(--diff-deleted-border); }
.diff-hunk-number { width: 4.5em; flex: 0 0 4.5em; text-align: right; padding-right: 1em; color: var(--text-muted); background: color-mix(in srgb, var(--shadow-color) 6.667%, transparent); user-select: none; }
.diff-hunk-sign { width: 2em; flex: 0 0 2em; text-align: center; color: var(--text-muted); user-select: none; }
.diff-hunk-text { white-space: pre; padding-right: var(--space-6); flex: 1; }
.diff-hunk-code.is-wrapped { min-width: 0; }
.diff-hunk-code.is-wrapped .diff-hunk-text { white-space: pre-wrap; overflow-wrap: anywhere; min-width: 0; }
.diff-no-newline { font: var(--text-xs)/20px var(--font-mono); color: var(--text-muted); padding-left: 12em; }
.diff-hunk-metadata { padding: var(--space-7); white-space: pre-wrap; overflow-wrap: anywhere; font: var(--text-md)/1.7 var(--font-mono); color: var(--text-secondary); }
@media (max-width: 800px) { .window-panel { --window-panel-inset: calc(min(300px, 40vw) + 24px); inset-block: 8px; right: 8px; } .window-panel-header { padding: var(--space-4); } .window-panel-header label { width: 100%; } .window-panel-header select { max-width: 100%; } .diff-hunk-number { width: 3em; flex-basis: 3em; } }

.diff-hunk-metadata pre { white-space: pre-wrap; overflow-wrap: anywhere; }

.window-panel { z-index: 35; }
.window-panel { touch-action: pan-x pan-y; }
.window-panel-primary, .window-panel-secondary { position: relative; box-shadow: inset 0 0 0 2px transparent; }
.window-panel [data-pane][data-focused=true] { box-shadow: inset 0 0 0 2px var(--accent-primary); }
.window-panel [data-pane] > * { max-height: 100%; }
.window-panel [data-pane] > .diff-tree-scroll, .window-panel [data-pane] > .diff-hunks-scroll { margin: 2px; min-height: 0; overscroll-behavior: contain; scrollbar-gutter: stable; }
.window-panel-minimized { left: auto; width: 40%; right: 12px; }
.window-panel-minimized .window-panel-primary { flex: 1; }
.window-panel-minimized .window-panel-header label { display: none; }
.diff-tree-ascii [data-scroll-tracked=true] { box-shadow: 0 2px var(--accent-warning); background: color-mix(in srgb, var(--diff-modified-fill) 40.000%, transparent); }
.diff-tree-ascii [data-scroll-tracked=true][aria-selected=true] { background: var(--selection-fill); box-shadow: 0 2px var(--accent-warning); }
.diff-coverage { color: var(--accent-warning); font: var(--text-xs)/1.4 var(--font-mono); margin-left: 12px; white-space: nowrap; text-decoration: none; }
.diff-tree-ascii .diagram-jump { margin-left: 8px; padding: 0 5px; }
.diff-hunk:focus-visible { outline: 2px solid var(--accent-primary); outline-offset: -2px; }
.change-inline-coverage { position: absolute; width: 145px; text-align: right; margin: 0; pointer-events: auto; font-size: var(--text-xs); z-index: 2; }
@media (max-width: 800px) { .window-panel-minimized { width: 40%; left: auto; } }
/* Panel resizing affects only the overlay, never the canvas viewport. */
.window-panel-resize { position: absolute; z-index: 5; touch-action: none; }
.window-panel-resize-left { left: 0; top: 0; bottom: 12px; width: 6px; cursor: ew-resize; }
.window-panel-resize-bottom { bottom: 0; left: 12px; right: 0; height: 6px; cursor: ns-resize; }
.window-panel-resize-corner { bottom: 0; left: 0; width: 14px; height: 14px; cursor: nesw-resize; }
.window-panel-resize:hover, .window-panel-resize:focus-visible { background: color-mix(in srgb, var(--accent-primary) 50.196%, transparent); }

.window-panel-tabbed { inset: 16px 16px auto auto; width: min(560px, calc(100% - min(348px, 43vw) - 16px)); height: min(680px, calc(100% - 32px)); min-width: 260px; min-height: 240px; max-width: calc(100% - min(348px, 43vw) - 16px); max-height: calc(100% - 32px); overflow: hidden; box-sizing: border-box; }
.window-panel-tabbed > .window-panel-resize-corner { width: 18px; height: 18px; }
.window-panel-tabbed > .window-panel-resize-corner::after { content: ''; position: absolute; bottom: 4px; left: 4px; width: 9px; height: 9px; background: repeating-linear-gradient(45deg, var(--text-muted) 0 1px, transparent 1px 4px); clip-path: polygon(0 0, 100% 100%, 0 100%); }
.window-panel-tab-close { margin-left: auto; }
.window-panel-tool { display: flex; flex: 1; min-height: 0; min-width: 0; overflow: auto; flex-direction: column; }
.window-panel-tool[hidden] { display: none; }
.window-panel-tool .diagram-search-panel { position: static; width: auto; max-height: none; flex: 1; box-shadow: none; border: none; }
.workspace-tools-open { position: absolute; top: 64px; right: 16px; z-index: 9; }
.llm-panel { min-height: 0; display: flex; flex-direction: column; flex: 1; }
.llm-panel .prompt-composer-layout { flex-direction: column; }
.llm-panel .prompt-composer-main { padding: var(--space-6); }
.llm-panel .prompt-revision-rail { max-height: 180px; }
.llm-mode { display: flex; gap: var(--space-4); padding: var(--space-6); align-items: center; flex-wrap: wrap; }
.llm-mode small { width: 100%; color: var(--muted); }
.llm-explorer-new { margin: 10px 0; }
.projection-join.llm-origin { color: var(--accent-success); background: var(--diff-added-fill); border-color: var(--accent-success); cursor: crosshair; touch-action: none; }
.projection-join.llm-origin:disabled { cursor: default; }
.llm-extension-edge { position: absolute; overflow: visible; pointer-events: none; color: var(--accent-success); z-index: 12; }
.llm-origin-preview { pointer-events: none; }

.mapping-whole-actions { position: absolute; right: 12px; top: 108px; z-index: 10; max-width: calc(100% - 24px); pointer-events: auto; }
.mapping-whole-actions [role=menu] { display: flex; flex-wrap: wrap; padding: var(--space-3); background: var(--panel-background); border: 1px solid var(--gutter); }

.workspace-tools-open, .llm-explorer-new, .mapping-whole-actions button { padding: var(--space-3) var(--space-5); border: 1px solid var(--gutter); border-radius: var(--control-radius); color: var(--fg); background: var(--control-background); font: var(--text-md) var(--font-mono); cursor: pointer; }

/* In chat mode, header controls move into a drawer over the canvas. */
.window-panel-compact { overflow: visible; }
.window-panel-compact > .window-panel-tool { overflow: hidden; border-radius: inherit; }
.window-panel button.window-panel-compact-close { position: absolute; top: 2px; right: 6px; z-index: 6; width: 24px; height: 24px; padding: 0; border: 0; background: transparent; color: var(--text-muted); font-size: 18px; line-height: 1; }
.window-panel button.window-panel-compact-close:hover { background: var(--surface-hover); color: var(--text-primary); }
.window-panel-compact .agent-chat-tabbar { padding-right: 38px; }
.window-panel button.window-panel-sidebar-toggle { position: absolute; top: 8px; right: 100%; width: 20px; height: 30px; padding: 0; border-radius: 5px 0 0 5px; z-index: 8; background: var(--surface-panel); }
.window-panel-sidebar { position: absolute; right: calc(100% + 24px); top: 0; width: 260px; max-width: calc(100vw - 48px); max-height: 100%; overflow: auto; overscroll-behavior: contain; scrollbar-width: thin; border: 1px solid var(--gutter); border-radius: var(--panel-radius); background: var(--surface-panel); box-shadow: var(--shadow-panel); z-index: 7; }
.window-panel-sidebar[hidden] { display: none; }
.window-panel-sidebar .window-panel-tabs { flex-wrap: wrap; }
@media (max-width: 600px) {
  .window-panel-sidebar { right: auto; left: 0; top: 0; width: 100%; }
}

.window-panel-prefix-hint { position: absolute; z-index: 100; bottom: 16px; left: 50%; transform: translateX(-50%); max-width: calc(100% - 32px); padding: 6px 10px; border: 1px solid var(--border-default); border-radius: 6px; background: var(--surface-panel); color: var(--text-primary); font: 12px/1.5 var(--font-mono); pointer-events: none; }
